begin;
do $$
declare a uuid; f uuid; other_f uuid; e uuid; tid uuid:=gen_random_uuid(); rate_id uuid:=gen_random_uuid(); qid uuid:=gen_random_uuid();
 mid1 text:='tsi210-test-'||gen_random_uuid(); mid2 text:='tsi210-test-'||gen_random_uuid(); eid text:='tsi210-test-expense-'||gen_random_uuid();
 q jsonb; r jsonb; replay jsonb; snapshot jsonb; rid uuid; d jsonb; count_rows integer; denied boolean;
begin
 select id into a from public.profiles where role='admin' limit 1;
 select id into f from public.profiles where role='foto' order by id limit 1;
 select id into other_f from public.profiles where role='foto' and id<>f limit 1;
 select id into e from public.profiles where role='editora' limit 1;
 if a is null or f is null or other_f is null or e is null then raise exception 'Se requieren admin, dos fotógrafos y editora para probar los permisos'; end if;
 insert into public.matches(id,data) values
 (mid1,jsonb_build_object('id',mid1,'date',current_date,'time','10:00','teams','Prueba A vs B','venue','Prueba','cat','Prueba','f1',f,'f2','','ed',e,'stage','listos','link','https://example.invalid/entrega','cov',jsonb_build_object('players',10,'price',200,'discount',200,'paid',1000))),
 (mid2,jsonb_build_object('id',mid2,'date',current_date,'time','12:00','teams','Prueba C vs D','venue','Prueba','cat','Prueba','f1',f,'f2','','ed',e,'stage','','cov',jsonb_build_object('players',20,'price',200,'paid',0)));

 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);set local role authenticated;
 r:=public.tsi210_command('rate.save',jsonb_build_object('id',rate_id,'version',0,'sport','Flag','package_name','Tarifa de prueba','unit','player','price_cents',20000,'max_discount_pct',10,'active',true),gen_random_uuid());
 if r->>'id'<>rate_id::text then raise exception 'No se creó la tarifa'; end if;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'role','authenticated')::text,true);set local role authenticated;
 r:=public.tsi210_command('team.save',jsonb_build_object('id',tid,'version',0,'team_name','Equipo de prueba','sport','Flag','whatsapp','8112345678'),gen_random_uuid());
 if r->>'owner_id'<>f::text then raise exception 'Propietario incorrecto'; end if;
 perform public.tsi210_command('team.link',jsonb_build_object('team_id',tid,'match_id',mid1),gen_random_uuid());
 rid:=gen_random_uuid();
 q:=public.tsi210_command('quote.save',jsonb_build_object('id',qid,'version',0,'team_id',tid,'rate_id',rate_id,'quantity',10,'unit_price_cents',20000,'discount_cents',15000),rid);
 replay:=public.tsi210_command('quote.save',jsonb_build_object('id',qid,'version',0,'team_id',tid,'rate_id',rate_id,'quantity',10,'unit_price_cents',20000,'discount_cents',15000),rid);
 if q<>replay or (q->>'total_cents')::bigint<>185000 then raise exception 'Error de cálculo o de idempotencia'; end if;
 denied:=false;begin perform public.tsi210_command('quote.save',jsonb_build_object('team_id',tid,'rate_id',rate_id,'quantity',10,'discount_cents',25000),gen_random_uuid());exception when sqlstate 'P0001' then denied:=true;end;if not denied then raise exception 'Se permitió descuento excesivo';end if;
 denied:=false;begin perform public.tsi210_command('quote.save',jsonb_build_object('team_id',tid,'rate_id',rate_id,'quantity',10,'costs','{}'::jsonb),gen_random_uuid());exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Fotógrafo registró costos internos';end if;
 denied:=false;begin perform public.tsi210_command('rate.save',jsonb_build_object('id',rate_id,'price_cents',1),gen_random_uuid());exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Fotógrafo alteró tarifa';end if;
 q:=public.tsi210_command('quote.status',jsonb_build_object('id',qid,'version',q->'version','status','sent'),gen_random_uuid());
 q:=public.tsi210_command('quote.status',jsonb_build_object('id',qid,'version',q->'version','status','accepted'),gen_random_uuid());
 d:=public.tsi210_command('delivery.update',jsonb_build_object('match_id',mid1,'version',0,'action','sent'),gen_random_uuid());
 d:=public.tsi210_command('delivery.update',jsonb_build_object('match_id',mid1,'version',d->'version','action','confirmed'),gen_random_uuid());
 if d->>'confirmed_by'<>f::text then raise exception 'No se registró recepción manual'; end if;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_f,'role','authenticated')::text,true);set local role authenticated;
 select count(*) into count_rows from public.tsi210_teams where id=tid;if count_rows<>0 then raise exception 'Otro fotógrafo leyó contactos ajenos';end if;
 select count(*) into count_rows from public.tsi210_quotes where id=qid;if count_rows<>0 then raise exception 'Otro fotógrafo leyó cotización ajena';end if;
 denied:=false;begin perform public.tsi210_command('quote.status',jsonb_build_object('id',qid,'version',q->'version','status','cancelled'),gen_random_uuid());exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Otro fotógrafo cambió cotización ajena';end if;
 denied:=false;begin perform public.tsi210_command('delivery.update',jsonb_build_object('match_id',mid1,'version',d->'version','action','confirmed'),gen_random_uuid());exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Otro fotógrafo modificó entrega';end if;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',e,'role','authenticated')::text,true);set local role authenticated;
 d:=public.tsi210_command('delivery.update',jsonb_build_object('match_id',mid1,'version',d->'version','action','correction','note','Corrección de prueba'),gen_random_uuid());
 if not (d->>'correction_open')::boolean or d->>'confirmed_at' is not null then raise exception 'La corrección no reabrió la entrega';end if;
 d:=public.tsi210_command('delivery.update',jsonb_build_object('match_id',mid1,'version',d->'version','action','resolved'),gen_random_uuid());
 if (d->>'correction_open')::boolean then raise exception 'No se resolvió la corrección';end if;
 denied:=false;begin perform public.tsi210_backup();exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Editora pudo generar respaldo administrativo';end if;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);set local role authenticated;
 rid:=gen_random_uuid();r:=public.tsi210_command('quote.convert',jsonb_build_object('id',qid,'version',q->'version','match_id',mid1),rid);
 replay:=public.tsi210_command('quote.convert',jsonb_build_object('id',qid,'version',q->'version','match_id',mid1),rid);
 if r<>replay or r->>'match_id'<>mid1 then raise exception 'Conversión duplicada o incorrecta';end if;
 insert into public.expenses(id,owner,data) values(eid,a::text,jsonb_build_object('id',eid,'uid',a,'date',current_date,'cat','Prueba de reparto','amount',100.01,'status','aprobado'));
 rid:=gen_random_uuid();r:=public.tsi210_command('expense.allocate',jsonb_build_object('expense_id',eid,'match_ids',jsonb_build_array(mid1,mid2),'method','equal'),rid);
 replay:=public.tsi210_command('expense.allocate',jsonb_build_object('expense_id',eid,'match_ids',jsonb_build_array(mid1,mid2),'method','equal'),rid);
 select count(*) into count_rows from public.tsi210_match_costs where source_expense_id=eid;
 if count_rows<>2 or (select sum(amount_cents) from public.tsi210_match_costs where source_expense_id=eid)<>10001 or r<>replay then raise exception 'Se perdieron centavos o se duplicaron costos';end if;
 denied:=false;begin update public.expenses set data=data||'{"amount":50}' where id=eid;exception when sqlstate 'P0001' then denied:=true;end;if not denied then raise exception 'Se redujo un gasto ya atribuido';end if;
 r:=public.tsi210_command('cost.save',jsonb_build_object('match_id',mid1,'category','travel','amount_cents',7500,'note','Costo de prueba'),gen_random_uuid());
 denied:=false;begin update public.tsi210_quotes set unit_price_cents=1 where id=qid;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Se permitió saltar el comando protegido';end if;
 if not exists(select 1 from public.tsi210_audit_log where entity='tsi210_match_costs' and actor_id=a) then raise exception 'Falta trazabilidad';end if;
 snapshot:=public.tsi210_backup();r:=public.tsi210_verify_restore(snapshot);
 if not (r->>'verified')::boolean or (r->>'live_data_modified')::boolean then raise exception 'No se verificó la restauración aislada';end if;
 reset role;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'role','authenticated')::text,true);set local role authenticated;
 r:=public.tsi210_state();if jsonb_array_length(r->'costs')<>0 or jsonb_array_length(r->'quote_costs')<>0 or jsonb_array_length(r->'audit')<>0 then raise exception 'Se expusieron costos o bitácora a fotógrafo';end if;
 reset role;
 perform set_config('request.jwt.claims','{"role":"anon"}',true);set local role anon;
 denied:=false;begin perform public.tsi210_state();exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Anónimo accedió al módulo';end if;
 reset role;
 raise notice 'TSI 2.1.0: tarifas, cotizaciones, roles, reintentos, conversión, entrega, correcciones, reparto, auditoría y restauración aislada APROBADOS';
end $$;
rollback;
